# Helpers for analysis/reproduce.ipynb: latent sense proportions in the three
# regressions, and the per-sentence logits the aspectual classes are fit to.
#
# The regressions are specified in brms. brms cannot estimate the weights of a
# multi-membership term, so each regression's Stan program is generated by
# brms, edited here so that the weights are parameters, and sampled through
# cmdstanr; the draws are then read back into the brmsfit, so that brms's
# post-processing applies to them.

# ---- sampling an edited program --------------------------------------------
# Sample `code` with `data` and read the draws into the brmsfit `b`.
sample_edited <- function(b, code, data, name, seed, warmup, iter, adapt_delta, chains = 4, cores = 4) {
  dir <- file.path("analysis/fits", paste0(name, "-csv")); dir.create(dir, showWarnings = FALSE, recursive = TRUE)
  model <- cmdstanr::cmdstan_model(cmdstanr::write_stan_file(code, dir = "analysis/fits", basename = name))
  fit <- model$sample(data, seed = seed, chains = chains, parallel_chains = cores, iter_warmup = warmup,
                      iter_sampling = iter - warmup, adapt_delta = adapt_delta, refresh = 500, output_dir = dir)
  b$fit <- brms:::read_csv_as_stanfit(fit$output_files())
  brms::rename_pars(b)
}
sense_draws <- function(m) {
  d <- posterior::as_draws_matrix(m)
  d[, grepl("^(rho|split)\\[|^eps$", colnames(d)), drop = FALSE]
}
# Write each sentence's posterior-mean weights into the brmsfit's data.
with_mean_weights <- function(m, tab) {
  d <- posterior::as_draws_matrix(m)
  W <- matrix(colMeans(d[, sprintf("Wt[%d,%d]", rep(seq_len(nrow(tab$items)), K_SLOTS), rep(seq_len(K_SLOTS), each = nrow(tab$items)))]),
              nrow(tab$items), K_SLOTS)
  i <- match(m$data$sentence, tab$items$sentence)
  for (k in seq_len(K_SLOTS)) m$data[[paste0("weight", k)]] <- W[i, k]
  m
}

# ---- latent sense proportions ----------------------------------------------
# Latent sense proportions for the multi-membership effect.
#
# A sense is a (PropBank roleset, concreteness) combination for which a
# contentful sentence was written. For each verb,
#   rho_v    ~ Dirichlet(1)          proportions of the verb's rolesets
#   n_v      ~ Multinomial(rho_v)    OntoNotes roleset counts
#   split_r  ~ Beta(1, 1)            share of roleset r that is concrete, for
#                                    rolesets with both concreteness levels
#   pi_s     = rho_r * split_r (or 1 - split_r, or 1)
# and eps ~ Beta(1, 4) discounts the senses of a verb that lie outside the set
# inferred for a bleached sentence from the contentful sentences it was
# constructed from. A sentence's weights over its verb's senses are
#   contentful: 1 on the sense it was written for
#   templatic:  pi
#   bleached:   pi * (1 if the sense is in the inferred set, else eps), normalized
K_SLOTS <- 4

sense_tables <- function() {
  inventory <- read_csv("data/manner-result-sentences.csv", show_col_types = FALSE) %>%
    mutate(sense_id = sub(":.*", "", propbank_sense),
           verb_sense = paste(propbank_sense, concreteness, sep = "_"))
  pb <- read_csv("data/propbank-sense-distribution.csv", show_col_types = FALSE) %>%
    dplyr::select(verb, sense_id = sense, count)
  senses <- inventory %>% distinct(verb, sense_id, concreteness, verb_sense) %>%
    mutate(sense = match(verb_sense, sort(unique(verb_sense)))) %>% arrange(sense)  # brms orders levels with sort()
  roles <- senses %>% distinct(verb, sense_id) %>% arrange(verb, sense_id) %>%
    left_join(pb, by = c("verb", "sense_id")) %>%
    mutate(count = ifelse(is.na(count), 0, count), role = row_number(),
           verb_index = as.integer(factor(verb)))
  senses <- senses %>% left_join(roles %>% dplyr::select(verb, sense_id, role), by = c("verb", "sense_id")) %>%
    group_by(role) %>% mutate(n_conc = n()) %>% ungroup()
  split_roles <- sort(unique(senses$role[senses$n_conc == 2]))
  senses <- senses %>% mutate(split = ifelse(n_conc == 2, match(role, split_roles), 0L),
                              first = as.integer(concreteness == "concrete"))
  stopifnot(all(senses$n_conc <= 2))
  # per-sentence slots
  items <- bind_rows(
    inventory %>% distinct(verb, sentence = sentence_contentful_episodic) %>% mutate(kind = 1L),
    inventory %>% distinct(verb, sentence = sentence_bleached_episodic) %>% mutate(kind = 2L),
    inventory %>% distinct(verb, sentence = sentence_templatic_episodic) %>% mutate(kind = 3L)) %>%
    arrange(sentence) %>% mutate(item = row_number())
  stopifnot(!anyDuplicated(items$sentence))
  own <- bind_rows(
    inventory %>% distinct(sentence = sentence_contentful_episodic, verb_sense),
    inventory %>% distinct(sentence = sentence_bleached_episodic, verb_sense)) %>% mutate(inset = 1L)
  slots <- items %>% inner_join(senses %>% dplyr::select(verb, verb_sense, sense), by = "verb", relationship = "many-to-many") %>%
    left_join(own, by = c("sentence", "verb_sense")) %>%
    mutate(inset = ifelse(is.na(inset), 0L, inset)) %>%
    group_by(item) %>% arrange(sense, .by_group = TRUE) %>% mutate(slot = row_number()) %>% ungroup()
  stopifnot(max(slots$slot) <= K_SLOTS)
  list(senses = senses, roles = roles, items = items, slots = slots, n_split = length(split_roles))
}

# Columns verb_sense1..K (slot labels) for a data frame with a `sentence` column,
# so that brms builds its grouping indices in the slot order used here.
slot_columns <- function(tab) {
  wide <- tab$slots %>% dplyr::select(sentence, slot, verb_sense) %>%
    pivot_wider(names_from = slot, values_from = verb_sense, names_prefix = "verb_sense")
  for (k in seq_len(K_SLOTS)) {
    v <- paste0("verb_sense", k)
    if (!v %in% names(wide)) wide[[v]] <- NA_character_
    wide[[v]] <- ifelse(is.na(wide[[v]]), wide$verb_sense1, wide[[v]])
    wide[[paste0("weight", k)]] <- as.numeric(k == 1)   # placeholders; the weights are parameters
  }
  wide
}

# Stan data for the sense block. `prior` is NULL for the first stage (the
# priors above and the count likelihood) or a list(rho_a, split_a, split_b,
# eps_a, eps_b) carrying the previous stage's posterior forward.
sense_standata <- function(tab, sentences, prior = NULL) {
  ni <- nrow(tab$items)
  M <- function(col, fill) { m <- matrix(fill, ni, K_SLOTS); m[cbind(tab$slots$item, tab$slots$slot)] <- tab$slots[[col]]; m }
  used <- M("inset", 0L); used[cbind(tab$slots$item, tab$slots$slot)] <- 1L
  ss <- M("sense", 0L); for (i in seq_len(ni)) ss[i, ss[i, ] == 0L] <- ss[i, 1]
  first <- is.null(prior)
  list(N_item = ni, item = match(sentences, tab$items$sentence), item_kind = tab$items$kind,
       slot_used = used, slot_in = M("inset", 0L), slot_sense = ss,
       N_sense = nrow(tab$senses), N_role = nrow(tab$roles), N_split = tab$n_split,
       N_sverb = max(tab$roles$verb_index),
       sense_role = tab$senses$role, sense_split = tab$senses$split, sense_first = tab$senses$first,
       role_verb = tab$roles$verb_index, role_count = tab$roles$count,
       rho_a = if (first) rep(1, nrow(tab$roles)) else prior$rho_a,
       split_a = as.array(if (first) rep(1, tab$n_split) else prior$split_a),
       split_b = as.array(if (first) rep(1, tab$n_split) else prior$split_b),
       eps_a = if (first) 1 else prior$eps_a, eps_b = if (first) 4 else prior$eps_b,
       use_counts = as.integer(first))
}

SENSE_DATA <- "
  // ---- latent sense proportions ----
  int<lower=1> N_item;  // sentences
  array[N] int<lower=1> item;  // sentence of each observation
  array[N_item] int<lower=1, upper=3> item_kind;  // 1 contentful, 2 bleached, 3 templatic
  array[N_item, 4] int<lower=0, upper=1> slot_used;  // the slot holds a sense of the verb
  array[N_item, 4] int<lower=0, upper=1> slot_in;  // the sense the sentence was written for, or in a bleached sentence's inferred set
  array[N_item, 4] int<lower=1> slot_sense;
  int<lower=1> N_sense;
  int<lower=1> N_role;
  int<lower=0> N_split;
  int<lower=1> N_sverb;
  array[N_sense] int<lower=1> sense_role;
  array[N_sense] int<lower=0> sense_split;
  array[N_sense] int<lower=0, upper=1> sense_first;
  array[N_role] int<lower=1> role_verb;
  vector<lower=0>[N_role] role_count;  // OntoNotes roleset counts
  vector<lower=0>[N_role] rho_a;
  vector<lower=0>[N_split] split_a;
  vector<lower=0>[N_split] split_b;
  real<lower=0> eps_a;
  real<lower=0> eps_b;
  int<lower=0, upper=1> use_counts;
"
SENSE_PARAMETERS <- "
  vector<lower=0>[N_role] rho_raw;  // unnormalized roleset proportions
  vector<lower=0, upper=1>[N_split] split;  // concrete share of a roleset with both concreteness levels
  real<lower=0, upper=1> eps;  // discount on senses outside a bleached sentence's inferred set
"
SENSE_TPARS_DECL <- "
  vector[N_role] rho;  // roleset proportions within verb
  vector[N_sense] pi_sense;  // sense proportions within verb
  matrix[N_item, 4] Wt;  // each sentence's weights over its verb's senses
"
SENSE_TPARS <- "
  {
    vector[N_sverb] tot = rep_vector(0, N_sverb);
    for (r in 1:N_role) tot[role_verb[r]] += rho_raw[r];
    for (r in 1:N_role) rho[r] = rho_raw[r] / tot[role_verb[r]];
  }
  for (s in 1:N_sense) {
    pi_sense[s] = rho[sense_role[s]];
    if (sense_split[s] > 0)
      pi_sense[s] *= sense_first[s] ? split[sense_split[s]] : 1 - split[sense_split[s]];
  }
  for (i in 1:N_item) {
    for (k in 1:4) {
      if (!slot_used[i, k]) Wt[i, k] = 0;
      else if (item_kind[i] == 1) Wt[i, k] = slot_in[i, k];
      else if (item_kind[i] == 3 || slot_in[i, k]) Wt[i, k] = pi_sense[slot_sense[i, k]];
      else Wt[i, k] = eps * pi_sense[slot_sense[i, k]];
    }
    Wt[i] /= sum(Wt[i]);
  }
"
SENSE_MODEL <- "
  // sense proportions: normalized gammas are Dirichlet(rho_a)
  target += gamma_lpdf(rho_raw | rho_a, 1);
  target += beta_lpdf(split | split_a, split_b);
  target += beta_lpdf(eps | eps_a, eps_b);
  if (use_counts) target += dot_product(role_count, log(rho));
"
# Edit a brms-generated program: the multi-membership weights W_g_k[n] become
# the parameters Wt[item[n], k].
edit_mm_stan <- function(code) {
  stopifnot(grepl("W_[0-9]+_[1-4]\\[n\\]", code))
  code <- gsub("W_[0-9]+_([1-4])\\[n\\]", "Wt[item[n], \\1]", code)
  code <- sub("\n  int prior_only;", paste0(SENSE_DATA, "\n  int prior_only;"), code, fixed = TRUE)
  code <- sub("\nparameters {\n", paste0("\nparameters {", SENSE_PARAMETERS), code, fixed = TRUE)
  code <- sub("\n  real lprior = 0;", paste0(SENSE_TPARS_DECL, "\n  real lprior = 0;", SENSE_TPARS), code, fixed = TRUE)
  code <- sub("\n  // priors including constants\n", paste0("\n  // priors including constants", SENSE_MODEL), code, fixed = TRUE)
  code
}
# Carry a posterior over the sense parameters forward as the next stage's
# prior, by matching moments: a Dirichlet for each verb's roleset proportions
# and a Beta for each split and for eps.
beta_mm <- function(x) { m <- mean(x); v <- var(x); k <- max(m * (1 - m) / v - 1, 1e-3); c(m * k, (1 - m) * k) }
carry_forward <- function(draws, tab) {
  rho <- draws[, sprintf("rho[%d]", seq_len(nrow(tab$roles))), drop = FALSE]
  a <- numeric(ncol(rho))
  for (v in unique(tab$roles$verb_index)) {
    j <- which(tab$roles$verb_index == v); m <- colMeans(rho[, j, drop = FALSE])
    if (length(j) == 1) { a[j] <- 1; next }
    vv <- apply(rho[, j, drop = FALSE], 2, var)
    a[j] <- m * median(m * (1 - m) / vv - 1)
  }
  sp <- if (tab$n_split > 0) sapply(seq_len(tab$n_split), function(k) beta_mm(draws[, sprintf("split[%d]", k)])) else matrix(0, 2, 0)
  e <- beta_mm(draws[, "eps"])
  list(rho_a = a, split_a = sp[1, ], split_b = sp[2, ], eps_a = e[1], eps_b = e[2])
}
# Renumber the senses to the level order brms gives the multi-membership
# grouping factor in `sd` (the standata built from `data`, whose columns
# verb_sense1..K came from slot_columns()).
align_senses <- function(tab, sd, data) {
  g <- sub("^J_([0-9]+)_1$", "\\1", grep("^J_[0-9]+_1$", names(sd), value = TRUE))
  lab <- unlist(lapply(seq_len(K_SLOTS), function(k) data[[paste0("verb_sense", k)]]))
  idx <- unlist(lapply(seq_len(K_SLOTS), function(k) sd[[sprintf("J_%s_%d", g, k)]]))
  map <- tapply(idx, lab, function(x) { stopifnot(length(unique(x)) == 1); x[1] })
  stopifnot(setequal(names(map), tab$senses$verb_sense), sd[[paste0("N_", g)]] == nrow(tab$senses))
  tab$senses$sense <- as.integer(map[tab$senses$verb_sense])
  tab$senses <- tab$senses[order(tab$senses$sense), ]
  tab$slots$sense <- as.integer(map[tab$slots$verb_sense])
  tab
}

# ---- per-sentence logits ---------------------------------------------------
# Per-sentence posterior draws of the linear predictor of each regression:
# the logit of choosing `in` (cloze) and the logit of an overlap response
# under `in` and under `for` (proportion), for an average participant and
# list, at numeral 1 and the sentence's modal time unit. The multi-membership
# sense effect is added draw by draw with that draw's sense weights.
sense_term <- function(m, items_idx, tab, coef = "Intercept") {
  d <- posterior::as_draws_matrix(m)
  r <- d[, grep(sprintf("^r_mmverb_sense.*,%s\\]$", coef), colnames(d)), drop = FALSE]
  stopifnot(ncol(r) == nrow(tab$senses))
  ni <- nrow(tab$items); ss <- matrix(0L, ni, K_SLOTS); used <- matrix(FALSE, ni, K_SLOTS)
  ss[cbind(tab$slots$item, tab$slots$slot)] <- tab$slots$sense; used[cbind(tab$slots$item, tab$slots$slot)] <- TRUE
  out <- matrix(0, nrow(d), length(items_idx))
  for (k in seq_len(K_SLOTS)) {
    W <- d[, sprintf("Wt[%d,%d]", items_idx, k), drop = FALSE]
    s <- ss[items_idx, k]; ok <- used[items_idx, k]
    out[, ok] <- out[, ok] + unclass(W)[, ok, drop = FALSE] * unclass(r)[, s[ok], drop = FALSE]
  }
  out
}
sentence_newdata <- function(fit_data, per_sent_eval, prep_pref = NULL, prep = NULL) {
  tmpl <- fit_data %>% distinct(sentence, .keep_all = TRUE) %>%
    dplyr::select(any_of(c("sentence", "verb", "verb_type", "generality", "argument_forms",
                           paste0("verb_sense", 1:K_SLOTS), paste0("weight", 1:K_SLOTS))))
  d <- per_sent_eval %>% inner_join(tmpl, by = c("verb", "sentence")) %>%
    mutate(time_unit = factor(eval_time_unit, levels = levels(fit_data$time_unit)), numeral = 1L,
           duration = paste("1", eval_time_unit, sep = "_"))
  if (!is.null(prep)) {
    d$preposition <- factor(prep, levels = levels(fit_data$preposition)); contrasts(d$preposition) <- -contr.sum(2)
    d <- d %>% left_join(prep_pref, by = "sentence")
  }
  d
}
RE_CLOZE <- ~ (1 | sentence) + (1 | argument_forms) + (1 + generality | verb) + (1 | time_unit) + (1 | duration)
RE_PROP  <- ~ (1 + preposition | sentence) + (1 + preposition * generality | verb) + (1 + preposition | argument_forms) + (1 | time_unit) + (1 | duration)
# Posterior draws of each sentence's three logits: choosing 'in' in the cloze
# task, and an overlap response under 'in' and under 'for' in the proportion
# task. Returns an array of draws x sentences x diagnostics.
sentence_logits <- function(m_cloze, m_prop, tab, per_sent_eval, prep_pref, seed = 2030493) {
  set.seed(seed)
  nd <- sentence_newdata(m_cloze$data, per_sent_eval)
  idx <- match(nd$sentence, tab$items$sentence)
  lp <- function(m, nd, re) brms::posterior_linpred(m, newdata = nd, re_formula = re, allow_new_levels = TRUE, sample_new_levels = "gaussian")
  cl <- lp(m_cloze, nd, RE_CLOZE) + sense_term(m_cloze, idx, tab)
  nin <- sentence_newdata(m_prop$data, per_sent_eval, prep_pref, "in"); nfor <- sentence_newdata(m_prop$data, per_sent_eval, prep_pref, "for")
  stopifnot(identical(nin$sentence, nd$sentence))
  s0 <- sense_term(m_prop, idx, tab, "Intercept"); s1 <- sense_term(m_prop, idx, tab, "preposition1")
  pin <- lp(m_prop, nin, RE_PROP) + s0 + s1      # preposition is coded for = -1, in = +1
  pfor <- lp(m_prop, nfor, RE_PROP) + s0 - s1
  # the two fits are separate, so their draws are independent and are paired by index
  S <- min(nrow(cl), nrow(pin))
  x <- array(c(cl[seq_len(S), ], pin[seq_len(S), ], pfor[seq_len(S), ]), c(S, ncol(cl), 3),
             dimnames = list(NULL, NULL, c("cloze", "overlap_in", "overlap_for")))
  list(sentence = nd$sentence, verb = nd$verb, generality = as.character(nd$generality), x = x)
}
# Aspectual match of sentences i and j: the probability that a reference
# sentence drawn from the materials does not separate the two on any of the
# three logits, averaged over posterior draws. A reference separates the pair
# on a logit if its own logit lies between theirs. x is draws x sentences x 3.
reference_match <- function(x, i, j) {
  sep <- matrix(FALSE, dim(x)[1], dim(x)[2])
  for (d in seq_len(dim(x)[3])) {
    lo <- pmin(x[, i, d], x[, j, d]); hi <- pmax(x[, i, d], x[, j, d])
    sep <- sep | (x[, , d] > lo & x[, , d] < hi)
  }
  1 - mean(sep[, -c(i, j)])
}

# ---- Experiment 2 ----------------------------------------------------------
# Same-sense for each pair: the probability that its two sentences have the
# same roleset under their sense weights, computed on each posterior draw of
# fit m and averaged over draws.
same_sense_prob <- function(m, tab, sentence1, sentence2) {
  d <- posterior::as_draws_matrix(m); ni <- nrow(tab$items)
  W <- array(unclass(d[, sprintf("Wt[%d,%d]", rep(seq_len(ni), K_SLOTS), rep(seq_len(K_SLOTS), each = ni))]), c(nrow(d), ni, K_SLOTS))
  role <- matrix(0L, ni, K_SLOTS)
  role[cbind(tab$slots$item, tab$slots$slot)] <- tab$senses$role[match(tab$slots$verb_sense, tab$senses$verb_sense)]
  i <- match(sentence1, tab$items$sentence); j <- match(sentence2, tab$items$sentence)
  sapply(seq_along(i), function(p) {
    out <- 0
    for (k in seq_len(K_SLOTS)) for (l in seq_len(K_SLOTS))
      if (role[i[p], k] > 0 && role[i[p], k] == role[j[p], l]) out <- out + W[, i[p], k] * W[, j[p], l]
    mean(out)
  })
}
sim_formula <- bf(similarity ~ (aspect_match_c + same_sense_c + genpair)^2 +
    (1 + aspect_match_c + same_sense_c + genpair | verb) +
    (1 + aspect_match_c + same_sense_c + genpair | participant) + (1 | sentence_pair))
